/**
 * Malmö Live Events Source
 * 
 * Fetches events from Malmö Live API.
 * API: https://malmolive.se/api/events
 * 
 * This source:
 * 1. Fetches events directly from Malmö Live API
 * 2. Parses and normalizes the response
 * 3. Queues events for processing
 */

import axios from 'axios';
import { rawEventsQueue } from '../queue';
import type { RawEventInput } from '@eventpulse/shared';

// Configuration
const MALMO_LIVE_API = 'https://malmolive.se/api/events';
const CITY = 'Malmö';

/**
 * Map Malmö Live API response to RawEventInput
 */
function mapMalmöLiveEvent(item: any): RawEventInput {
  const title = item.title || 'Untitled Event';

  // Parse date and time
  let start_time = '';
  let end_time = null;
  if (item.field_date_time) {
    const dt = new Date(item.field_date_time);
    start_time = dt.toISOString();
  }

  const venue_name = item.field_venue || 'Malmö Live';
  const venue_address = ''; // API doesn't provide full address

  // Parse keywords for categories
  const keywords = item.field_keywords_target_id || '';
  const categories = parseCategories(keywords);

  // Parse price
  const price_low = parseFloat(item.price_low) || 0;
  const price_high = parseFloat(item.price_high) || 0;
  const is_free = price_low === 0 && price_high === 0;

  // Build ticket URL
  let ticket_url: string | null = null;
  if (item.buy_link__uri) {
    // Extract URL from HTML anchor tag if present
    const urlMatch = item.buy_link__uri.match(/href="([^"]+)"/);
    ticket_url = urlMatch ? urlMatch[1] : item.buy_link__uri;
  }

  // Build event URL
  const event_url = item.view_node ? `https://malmolive.se${item.view_node}` : null;
  ticket_url = ticket_url || event_url;

  // Build image URL
  let image_url: string | null = null;
  if (item.field_media_image_1) {
    image_url = `https://malmolive.se${item.field_media_image_1}`;
  }

  // Source ID - prefer tessitura_instance_id (unique per performance)
  // fall back to tessitura_event_id (same for all performances of an event)
  const source_id = item.tessitura_instance_id || item.tessitura_event_id || null;

  // Detect language (API returns Swedish content)
  const detected_language: 'sv' | 'en' | 'other' | null = 'sv';

  return {
    title,
    description: item.field_text_plain_long || null,
    start_time,
    end_time,
    venue_name,
    venue_address,
    lat: 55.6050, // Malmö city center coordinates
    lng: 13.0038,
    categories,
    is_free,
    price_min_sek: price_low > 0 ? price_low : null,
    price_max_sek: price_high > 0 ? price_high : null,
    ticket_url,
    image_url,
    source: 'malmo-live',
    source_id,
    detected_language,
    raw_payload: item,
  };
}

/**
 * Parse keywords into category slugs
 */
function parseCategories(keywords: string): string[] {
  const categories: string[] = [];
  const lowerKeywords = keywords.toLowerCase();

  if (lowerKeywords.includes('pop') || lowerKeywords.includes('rock') || 
      lowerKeywords.includes('jazz') || lowerKeywords.includes('symfoni') ||
      lowerKeywords.includes('opera') || lowerKeywords.includes('musik')) {
    categories.push('music');
  }

  if (lowerKeywords.includes('barn') || lowerKeywords.includes('familj')) {
    categories.push('barn');
  }

  if (lowerKeywords.includes('dans') || lowerKeywords.includes('balett')) {
    categories.push('theatre');
  }

  if (lowerKeywords.includes('underhållning') || lowerKeywords.includes('humor') ||
      lowerKeywords.includes('komedi')) {
    categories.push('nightlife');
  }

  // Default to culture if no specific category matched
  if (categories.length === 0) {
    categories.push('culture');
  }

  return categories;
}

/**
 * Main scraper function - fetches and processes Malmö Live events
 */
export async function scrapeMalmolive(): Promise<string> {
  console.log('[malmolive] Starting scrape from Malmö Live API...');

  let totalQueued = 0;

  try {
    const response = await axios.get(MALMO_LIVE_API, {
      headers: {
        'User-Agent': 'EventPulse/1.0',
        'Accept': 'application/json',
      },
      timeout: 30000,
    });

    if (response.status !== 200) {
      console.warn(`[malmolive] API returned status ${response.status}`);
      return 'failed';
    }

    const data = response.data;

    if (!Array.isArray(data)) {
      console.warn('[malmolive] Unexpected data format - expected array');
      return 'failed';
    }

    console.log(`[malmolive] Received ${data.length} events from API`);

    // Filter to future events only
    const now = new Date();
    const oneYearFromNow = new Date();
    oneYearFromNow.setFullYear(oneYearFromNow.getFullYear() + 1);

    let validCount = 0;
    let queuedCount = 0;

    for (const item of data) {
      // Skip events without date
      if (!item.field_date_time) continue;

      const eventDate = new Date(item.field_date_time);

      // Only process future events within 1 year
      if (eventDate < now || eventDate > oneYearFromNow) {
        continue;
      }

      validCount++;

      // Map to RawEventInput format
      const rawEvent = mapMalmöLiveEvent(item);

      // Generate stable queue key
      const queueKey = rawEvent.source_id 
        ? `malmo-live:${rawEvent.source_id}`
        : `malmo-live:${rawEvent.title}:${rawEvent.start_time}`;

      // Queue for processing
      await rawEventsQueue.add(queueKey, rawEvent);
      queuedCount++;
    }

    console.log(`[malmolive] Validated ${validCount} future events, queued ${queuedCount}`);
    totalQueued = queuedCount;

  } catch (error) {
    const message = error instanceof Error ? error.message : 'Unknown error';
    console.error(`[malmolive] Failed to fetch events: ${message}`);
    return 'failed';
  }

  console.log(`[malmolive] Total queued: ${totalQueued} events`);
  return totalQueued > 0 ? 'completed' : 'failed';
}

